  </form>
  <h2>Jobs</h2>
  <ul data-testid="job-list"></ul>
  <script>
    const list = document.querySelector('[data-testid="job-list"]');
    const alert = document.querySelector('[data-testid="form-error"]');
    async function refresh() {
      try {
        const response = await fetch('/api/jobs');
        if (!response.ok) return;
        const { jobs } = await response.json();
        list.replaceChildren(...jobs.map(job => {
          const item = document.createElement('li');
          item.dataset-testid = 'job-item'; item.dataset.jobId = job.id;
          const title = document.createElement('strong'); title.textContent = job.input;
          const status = document.createElement('span'); status.dataset.testid = 'job-status'; status.textContent = job.status;
          const progress = document.createElement('span'); progress.dataset.testid = 'job-progress'; progress.textContent = `${job.progress.completed}/${job.progress.total}`;
          const result = document.createElement('div'); result.dataset.testid = 'job-result';
          result.textContent = job.result ? job.result.output : job.error || '';
          const meta = document.createElement('div'); meta.className = 'meta';
          meta.append('Status: ', status, ' · Progress: ', progress);
          item.append(title, meta, result);
          return item;
        }));
      } catch { /* next poll will retry */ }
    }
    document.querySelector('[data-testid="job-form"]').addEventListener('submit', async event => {
      event.preventDefault(); alert.textContent = '';
      const form = event.currentTarget;
      const values = new FormData(form);
      const payload = { input: values.get('input'), steps: Number(values.get('steps')), failAttempts: Number(values.get('failAttempts')) };
      try {
        const response = await fetch('/api/jobs', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(payload) });
        const body = await response.json();
        if (!response.ok) {
          const fields = body.error?.fields || [];
          alert.textContent = fields.length ? fields.map(field => `${field.field}: ${field.message}`).join(' ') : body.error?.message || 'Submission failed.';
          return;
        }
        form.elements.input.value = '';
        await refresh();
      } catch { alert.textContent = 'Unable to submit job.'; }
    });
    refresh(); setInterval(refresh, 500);
  </script>
</body>
